export const CROSS_REFS_FROM_OTHERS: { animal: AnimalType; phase: number; text: string; mentions: AnimalType }[] = [
  { animal: 'fennec_fox', phase: 3, text: "Tock hears downward the way I hear outward, and this week we compared logs at last, hers in knocks and mine in breaths. They are the same ledger, friend, kept from two windows. She is the only creature in this house whose ears I would trust over my own, and she says the thing below keeps perfect time. I have started sleeping better since she said it. A rhythm that careful is not a thing that pounces.", mentions: 'aye_aye' },
  { animal: 'wombat', phase: 3, text: "Tock laid her chalk map over my tunnel drawings, her hollows above, my galleries below, and the two lines nested like a tongue in a groove. Thirty years I dug my half of that shape without knowing it had another half. She knew inside a season. That aye-aye reads a house the way I read ground, and I'll tell you what I told her: between her ceiling and my floor, there's nothing left in this building we haven't heard.", mentions: 'aye_aye' },
  { animal: 'owl', phase: 3, text: "The oldest text has a tower in it, and a bell, and beneath the bell an instruction I had catalogued for years as ornament. Then Tock arrived, and braided a rope, and I watched ornament become itinerary. Her people were called omens once, you know. The etymology is kinder than the villages were: omen, at root, is simply that which is heard. She has been hearing for all of us. I have amended the catalogue.", mentions: 'aye_aye' },
  { animal: 'fennec_fox', phase: 4, text: "Tock is at her rope tonight, and of every sound this house is about to make, hers is the one my ears are saved for. One ring, held sixty years. I have kept the watch my whole life for a sound worth hearing first, friend, and I am giving this one away freely. Let her hear it first. She kept its silence. The rest of us only kept time.", mentions: 'aye_aye' },
  { animal: 'wombat', phase: 4, text: "I checked Tock's tower tonight, every course and joint, and it will hold her ring and ten more besides. Then I came down to my stone to wait for the word from the other end. She sends it from above and I receive it below, the knocker and the digger, the two trades that always knew this house was hollow on purpose. When you hear the bell, that's her hand, and a truer hand was never set to a rope. I braided none of it and I'd still vouch for every strand.", mentions: 'aye_aye' },
];

